using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Threading;using FateLauncher;
public static class LiveDiscoveryTests {
 public static void Main(string[] args) {try{string work=Path.GetFullPath(args[0]),expected=Path.GetFullPath(args[1]);var timer=Stopwatch.StartNew();var hits=new Discovery(CancellationToken.None).Common(Path.Combine(work,"build"),new Settings());Console.WriteLine("Quick: "+hits.Emulators.Count+" emulator(s), "+hits.Memsticks.Count+" profile(s)");var deep=new Discovery(CancellationToken.None,null,50000,45).Devices(Discovery.DeviceRoots(Path.Combine(work,"build")),32,n=>Console.WriteLine("Visited "+n));hits.Merge(deep);hits.Prefer64Bit();string memory;if(!hits.Emulators.Contains(expected,StringComparer.OrdinalIgnoreCase)||!hits.EmulatorMemsticks.TryGetValue(expected,out memory))throw new Exception("Actual player installation not discovered");if(!File.Exists(Path.Combine(Engine.PspRoot(memory),"SYSTEM","ppsspp.ini")))throw new Exception("Actual memory config missing");Json.Write(Path.Combine(work,"live-discovery.json"),new{status="PASS",seconds=timer.Elapsed.TotalSeconds,expected_emulator=expected,paired_memstick=memory,emulators=hits.Emulators,memsticks=hits.Memsticks,directories=hits.Directories,limited=hits.Limited});Console.WriteLine("PASS actual player PPSSPP + memory stick: "+expected+" -> "+memory);}catch(Exception e){Console.Error.WriteLine(e);Environment.ExitCode=1;}}
}
